function extractUrls(text, opts){
  opts=opts||{}; var t=String(text||'');
  var re=/https?:\/\/[^\s<>"'\)\]】]+/gi;
  var m, out=[], seen={};
  while((m=re.exec(t))!==null){
    var u=m[0].replace(/[.,;:!?'")\]]+$/,'');
    if(opts.stripQuery){ var qi=u.indexOf('?'); if(qi>=0) u=u.slice(0,qi); }
    if(!u) continue;
    if(opts.unique){ if(seen[u]) continue; seen[u]=1; }
    out.push(u);
  }
  return {ok:true, urls:out, count:out.length};
}

var EXPORTS={extractUrls:extractUrls};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.UrlExtractForgePure = EXPORTS; }
